def WitnessCoverage (s : System Ω Λ) : Prop :=
  s.ExactWitness {r.A} ∧ s.ExactWitness {r.B, r.T} ∧
  s.ExactWitness (insert r.B r.E) ∧ s.Covers {r.A, r.B} ∧
  ∀ e ∈ r.E, s.Covers {r.A, r.T, e}

